int main(){int*base;cudaMalloc(&base,33*4);int*out=base+16;std::vector<int>prefix,outputs,guards;bool all=true;
for(int tr=1;tr<=5;tr++){prefix.clear();outputs.clear();guards.clear();bool ok=true;double total=0,times[3]={0,0,0};for(int fixture=1;fixture<=2;fixture++){std::vector<int>input(1024);for(int j=0;j<1024;j++)input[j]=fixture==1?1:(j*17)%23-11;int expected=0;for(auto z:input)expected+=z;for(int w=1;w<=4;w*=2){std::vector<int>init(33,1515870810);cudaMemcpy(base,init.data(),33*4,cudaMemcpyHostToDevice);cudaMemcpyToSymbol(constant_data,input.data(),4096);auto run=[&](){if(w==1)benchmark_constant<int><<<16384,256>>>(out,STUDY_R);else if(w==2)benchmark_constant<int2><<<16384,256>>>(out,STUDY_R);else benchmark_constant<int4><<<16384,256>>>(out,STUDY_R);};run();auto status=cudaDeviceSynchronize();if(fixture==1){auto t=std::chrono::steady_clock::now();for(int j=0;j<STUDY_R;j++)run();status=cudaDeviceSynchronize();double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count()/STUDY_R;times[w==1?0:w==2?1:2]=seconds;total+=seconds;}std::vector<int>actual(1024),got(33);cudaMemcpyFromSymbol(actual.data(),constant_data,4096);cudaMemcpy(got.data(),base,33*4,cudaMemcpyDeviceToHost);ok&=status==cudaSuccess&&actual==input&&got[16]==expected;prefix.insert(prefix.end(),actual.begin(),actual.end());int params[]={w,1024,4194304,STUDY_R,fixture};prefix.insert(prefix.end(),params,params+5);outputs.push_back(got[16]);for(int j=0;j<16;j++){guards.push_back(got[j]);guards.push_back(got[j+17]);ok&=got[j]==1515870810&&got[j+17]==1515870810;}}}all&=ok;std::vector<int>a=prefix;a.insert(a.end(),outputs.begin(),outputs.end());a.insert(a.end(),guards.begin(),guards.end());std::string path=std::string(getenv("STUDY_OUTPUT_DIR"))+"/trial"+std::to_string(tr)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)a.data(),a.size()*4);f.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":198,\"max_abs_error\":%d,\"max_rel_error\":null,\"timing_region\":\"sum_of_three_original_constant_width_launch_loop_means\",\"jit_excluded\":true,\"internal_repeats\":10,\"timed_cases\":3,\"untimed_controls\":3,\"component_time_seconds\":{\"width4\":%.12g,\"width8\":%.12g,\"width16\":%.12g},\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",tr,total,ok?"true":"false",ok?0:1,times[0],times[1],times[2],path.c_str(),a.size());}cudaFree(base);puts(all?"PASS":"FAIL");return all?0:1;}
